args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?filmOlder ?filmOlderLabel WHERE {
  VALUES (?f1 ?f2) { (dbr:Le_droit_à_la_vie dbr:Heaven_Without_Love) }
  ?f1 dbo:director ?d1 .
  ?f2 dbo:director ?d2 .
  ?d1 dbo:birthDate ?b1 .
  ?d2 dbo:birthDate ?b2 .
  FILTER(?b1 < ?b2)  # earlier birth date => older
  BIND(?f1 AS ?filmOlder)
  OPTIONAL { ?filmOlder rdfs:label ?filmOlderLabel . FILTER (langMatches(lang(?filmOlderLabel), "en")) }
}

